import{c as t,ao as l,ah as n,L as e,O as p,I as i,Q as h,aY as k,P as r,o as d}from"./chunks/framework.YKVbmyBD.js";const m=JSON.parse('{"title":"MC服务器性能优化","description":"","frontmatter":{},"headers":[],"relativePath":"web-src/fovlin-notes/build-server-guide/1-6.md","filePath":"web-src/fovlin-notes/build-server-guide/1-6.md"}'),o={name:"web-src/fovlin-notes/build-server-guide/1-6.md"};function c(g,s,u,E,y,b){const a=l("center");return n(),e("div",null,[s[1]||(s[1]=p('<h1 id="mc服务器性能优化" tabindex="-1">MC服务器性能优化 <a class="header-anchor" href="#mc服务器性能优化" aria-label="Permalink to “MC服务器性能优化”">​</a></h1><h2 id="服务器性能指标" tabindex="-1">服务器性能指标 <a class="header-anchor" href="#服务器性能指标" aria-label="Permalink to “服务器性能指标”">​</a></h2><p>在开始优化你的服务器之前，你应该了解一些 MC 的性能指标。</p><p>MC 服务器中存在一些性能指标，保证这些指标在正常的范围内，可以让你的玩家在服务器中得到流畅的体验。</p><p>推荐在服务器上安装 TabTps 插件来方便观察服务器的一些性能指标。</p><h3 id="tps" tabindex="-1">TPS <a class="header-anchor" href="#tps" aria-label="Permalink to “TPS”">​</a></h3><p>tps 为每秒进行的游戏刻数量，正常游戏中，每秒游戏会进行20刻，如果服务器卡顿，tps会显著下降，只要你的服务器没有过载，tps 应保持 20。</p><p>tps 与下文的 mspt 有着很大的关系，mspt 的数值直接决定了 tps 的高低。</p><h3 id="mspt" tabindex="-1">MSPT <a class="header-anchor" href="#mspt" aria-label="Permalink to “MSPT”">​</a></h3><p>mspt 为计算一个游戏刻度所需要的时间，单位为毫秒/ms（一秒为 1000ms），该指标的数值将直接影响 tps，mspt 在大于 50 时，即处理一个游戏刻需要的时间大于 50ms，换算下来，服务器将无法在 1s 内计算 20 个游戏刻，tps 会明显下降，正常服务器的 mspt 应保持在 50 以下。</p><p>mspt 的数值与游戏内一切占用 CPU 的行为有关，占用越高，mspt 数值越高。</p><div class="tip custom-block"><p class="custom-block-title custom-block-title-default">TIP</p><p>MC 的大部分运算都在单线程上，很容易出现CPU的一个核心跑满，其他核心占用非常低的情况，<strong>当主线程所在的核心跑满时，mspt 就会显著升高</strong>。</p><p>主线程核心是不固定的，会在所有的核心之间变动，也很容易注意到会有一个核心占用达到 100%，而其他核心占用仅仅 10~20% 的情况，这很正常。</p></div><h3 id="ping" tabindex="-1">ping <a class="header-anchor" href="#ping" aria-label="Permalink to “ping”">​</a></h3><p>ping 为向服务器发送数据包，直到收到回应所需的时间，单位为毫秒，ping值越大，延迟也就越高，当服务器负载过高时，服务器可能无法处理请求，也会导致 ping值过高。</p><p>在保证服务器主线程所在的核心负载不会过高的情况下，该数值可以可以通过优化网络来调整，在这里不会着重对此项进行优化。</p><p>安装 TabTps 插件，服务器游戏内按下 tab 键可以观察到服务器的这些性能指标。（来自群友的截图）</p><p><img src="'+d+`" alt=""></p><h2 id="进行优化" tabindex="-1">进行优化 <a class="header-anchor" href="#进行优化" aria-label="Permalink to “进行优化”">​</a></h2><p>了解上述的指标后，我们可以开始优化服务端，最应该注意的是 mspt 的数值，也就是减少 CPU 的占用，以下几个因素最容易占用 CPU。</p><ul><li><p>实体数量</p></li><li><p>生物AI</p></li><li><p>复杂的红石电路</p></li><li><p>区块的生成</p></li></ul><h3 id="预生成区块" tabindex="-1">预生成区块 <a class="header-anchor" href="#预生成区块" aria-label="Permalink to “预生成区块”">​</a></h3><p>生成新的区块文件会消耗大量的性能，可以选择提前生成区块文件，仅需生成一次文件，这样当玩家在地图中游玩的时候，服务器仅需将区块数据发送给玩家即可。</p><p><strong>使用 <a href="https://modrinth.com/plugin/chunky?loader=paper" target="_blank" rel="noreferrer">Chunky</a> 插件来提前生成区块文件</strong></p><p>Chunky 同时也是一个模组，在客户端也可以使用，且方法相同，用法如下。</p><p>快速开始使用：</p><ul><li>chunky radius &lt;radius&gt; 设置半径</li><li>chunky center [&lt;x&gt; &lt;z&gt;] 设置中心块</li><li>chunky start 在当前选区中开始新生成</li><li>chunky pause 暂停并保存当前区块生成任务</li><li>chunky continue 继续运行当前或保存的区块生成任务</li><li>chunky cancel 停止并取消当前运行中的区块生成任务</li><li>chunky progress 在游戏中显示所有任务的预生成进度</li></ul><p>Chunky 默认选择（0，0）作为中心，500 作为半径，直接使用以下命令会以默认值开始生成:</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>/chunky start</span></span></code></pre></div><p>假设我们以世界（256，256）为中心，生成半径 1280 格的区块文件，可以这样输入命令：</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>/chunky radius 1280</span></span>
<span class="line"><span></span></span>
<span class="line"><span>/chunky center 256 256</span></span>
<span class="line"><span></span></span>
<span class="line"><span>/chunky start</span></span></code></pre></div><p>在控制台会产生如下输出：</p><div class="language-log"><button title="Copy Code" class="copy"></button><span class="lang">log</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">05:54:49</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;"> INFO</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]: [Chunky] Task started in world for the square region centered at </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1280</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1280</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> with radius </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1280</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">05:54:49</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;"> INFO</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]: [Chunky] Task running for world. Processed: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">51</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> chunks (</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">21</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">%), ETA: </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">0:00:13</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, Rate: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">320</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">8</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> cps, Current: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">13</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">2</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">05:54:50</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;"> INFO</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]: [Chunky] Task running for world. Processed: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">451</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> chunks (</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">10</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">67</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">%), ETA: </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">0:00:09</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, Rate: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">380</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">9</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> cps, Current: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">13</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">16</span></span></code></pre></div><p>更多命令不做过多赘述，参考如下：</p><ul><li>chunky selection 展示当前选区</li><li>chunky world [world] 设置选中的世界</li><li>chunky shape &lt;shape&gt; 设置目标形状</li><li>chunky center [&lt;x&gt; &lt;z&gt;] 设置中心块</li><li>chunky worldborder 设置中心和半径以匹配所选世界的世界边界</li><li>chunky spawn 设置中心至出生点</li><li>chunky corners &lt;x1&gt; &lt;z1&gt; &lt;x2&gt; &lt;z2&gt; 根据角坐标设置选区</li><li>chunky pattern &lt;pattern&gt; 设置首选生成模式</li><li>chunky silent 开关显示更新信息</li><li>chunky quiet &lt;interval&gt; 设置更新消息的静默间隔(以秒为单位)</li><li>chunky reload 重新加载配置</li><li>chunky trim 删除选区之外的块</li></ul><h3 id="关闭不必要的生物ai" tabindex="-1">关闭不必要的生物AI <a class="header-anchor" href="#关闭不必要的生物ai" aria-label="Permalink to “关闭不必要的生物AI”">​</a></h3><p>村民的 AI 是所有生物中最复杂的，对 CPU 的占用也非常高，当服务器中存在过多的村民时，过多的村民AI会吃掉服务器的大部分性能，禁用不必要的村民的 AI 是非常必要的。</p><p><strong>修改 nbt 来禁用生物的AI</strong></p><p>使用 /data 命令可以修改 nbt 数据，在村民的 nbt 标签中插入 {NoAI:&quot;1b&quot;} 即可禁用村民的生物 AI，使用以下命令修改村民的 nbt 标签来禁用 AI</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>/data merge entity @e[limit=1,type=villager,sort=nearest,distance=..5,nbt=!{NoAI:&quot;1b&quot;}] {{NoAI:&quot;1b&quot;}}</span></span></code></pre></div><p>此命令将选择5格内距离你最近的1名没有禁用 AI 的村民，并禁用其生物 AI。</p><p>如果批量禁用也很简单，仅需将以下命令放入循环型命令方块中，然后围绕着所有的村民跑一圈即可。</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>execute at &lt;你的游戏ID&gt; run data merge entity @e[limit=1,type=villager,sort=nearest,distance=..5,nbt=!{NoAI:&quot;1b&quot;}] {{NoAI:&quot;1b&quot;}}</span></span></code></pre></div><div class="danger custom-block"><p class="custom-block-title custom-block-title-default">DANGER</p><p>不要禁用交易村民的AI，这会使村民无法正常补货！！！</p></div><br><br><br>`,46)),i("p",null,[i("em",null,[i("strong",null,[h(a,null,{default:k(()=>[...s[0]||(s[0]=[r("--- 由 柏茯灵_RsDline 编写 ---",-1)])]),_:1})])])])])}const f=t(o,[["render",c]]);export{m as __pageData,f as default};
